content.content:
        hold: Cell.new(none),
        under: Cell.new(empty),
        was_hold: Cell.new(none),
        was_under: Cell.new(empty),
        by_order: Cell.new(false),
        step: Cell.new(stepless),
        route: Cell.new(""),
        said: said,
        window: Cell.new(unwindowed),
        counted: counted,
        placed: Cell.new(unplaced),
        extent: Cell.new(0),
        geometry: geometry,
        limit: limit,
        pin: Cell.new(nowhere),
        pin_at: Cell.new(-1),
        reveal: Cell.new(nowhere),
        honored: Cell.new(0),
        entry: Cell.new(0 - 1),
    }
}

impl Standing {
    /// A paint begins at this standing, the walk's root: nothing is said
    /// yet, and what stands becomes what stood.
    fn begun() {
        self.said.set([])
        self.counted.set(0)
        // A paint's root is drawn under no node, so it always carries the theme it is drawn in.
        self.entry.set(0 - 1)
        self.opened()
    }

    /// What the walk said this paint.
    fn warnings() -> List<string> { self.said.get() }

    /// The walk says `words`, once a paint.
    fn says(words: string) {
        if !self.said.get().contains(words) { self.said.push(words) }
    }

    /// A paint reaches this standing: what stands becomes what stood.
    fn opened() {
        self.was_hold.set(self.hold.get())
        self.was_under.set(self.under.get())
        self.hold.set(null)
        self.under.set([])
    }

    /// The standings under this one at `steps`, each opened: the one
    /// that stood at a step, else a new one. A step nobody names is
    /// gone with everything under it. `shared` says which steps are told
    /// from a sibling's by order alone; `drawn` whether this standing's
    /// own node is drawn, so the path under it starts over. A standing found
    /// again keeps its path and route: who it is is where it stands, so they
    /// are made once, when it first stands.
    fn children(steps: List<Step>, shared: List<bool>, drawn: bool) -> List<Standing> {
        let was = self.was_under.get()
        let stood = StepTable.of([u.step for u in was])
        let found = [stood.find(s) for s in steps]
        let now = [Under {
            step: s,
            standing: if found[j] == null { stands_in(self.said, self.counted, self.geometry, self.limit) } else { was[found[j]!].standing },
        } for j, s in steps]
        let above = if drawn { null } else { self.step.get() }
        for j, u in now {
            u.standing.opened()
            u.standing.by_order.set(shared[j])
            u.standing.entry.set(self.entry.get())
            if found[j] == null { self.first_stands(u, above) }
        }
        self.under.set(now)
        [u.standing for u in now]
    }

    /// A standing under this one at the step of `u`, standing there for the first time: its path under
    /// the nearest drawn node (`above`), and its route, the one text it is found by from a target.
    fn first_stands(u: Under, above: Step?) {
        u.standing.step.set(if above == null { u.step } else { Step.Through(above!, u.step) })
        u.standing.route.set("${self.route.get()}/${u.step.spelled()}")
    }

    /// `children`, for the rows of a WINDOWED list: `steps` are the rows in
    /// the window, opened as `children` opens them, the first at index
    /// of `at_rows`. A standing that holds an instance and stood at a step outside
    /// the window stays, unopened, while its row is in the source — what a
