fn look_under(scope: string, t: Theme) -> List<string> {
    let rules = look_rules(t)
    ["${[scope + part + pseudo_of(r.state) for part in parts([q.prim for q in rules if alike(q, r)])].join(",")}{${r.decls}}" for i, r in rules if !rules.slice(0, i).any(alike(it, r))]
