// proves: after a paint, the page's button hears what the view just built
// would, in every mode. A local a handler captured by copy that came from a
// state read, or from a call the analysis cannot see into (`now_ns` here),
// takes the full paint rather than an exact turn, so no handler is left
// holding a stale value.
use @std.ui.components.{button, column, text}
use @std.ui.realize.dom.live.{live}
use @std.ui.style.theme.{default_theme}
use @std.ui.realize.html.element.{Element}
use @std.ui.realize.dom.live.{Live}
use @std.ui.realize.tests.support.{seat_for}
use @std.ui.tree.seats.{Seat}
use @std.ui.tree.identity.{NodeId}
use @std.ui.tree.node.{Node}
use @std.time.{now_ns}

state n: int = 1
state m: int = 10
state out: int = 0

fn view() -> column {
    let seen = n
    let stamp = now_ns()
    column {
        text "m=${m}"
        button "go" { on press { out = seen + m + stamp } }
    }
}

/// The seat a std button declares for a press.
fn press() -> Seat { seat_for(.Press) }

fn presses(es: List<Element>) -> List<NodeId> { [i for e in es for i in presses_of(e)] }

fn presses_of(e: Element) -> List<NodeId> {
    match e {
        .Text(_) -> [],
        .Tag(t) -> if t.hears.any(it.seat == press()) { [t.id] } else { [] }.concat(presses(t.kids)),
    }
}

/// What a click on the page's button leaves in `out`.
fn clicked(page: Live) -> int {
    out = 0
    let _ = page.fire(presses(page.page.get())[0], press(), null)
    out
}

/// What the button of the view just built would leave: the value the page's
/// handler must hear.
fn built(tree: Node) -> int {
    out = 0
    tree.children[1].events[0].fire(null)
    out
}

/// Whether a paint of the view leaves the page's button hearing what the tree it
/// drew does.
fn hears_fresh(page: Live) -> bool {
    let tree = page.drawn(view())
    let _ = page.paint_drawn(tree)
    clicked(page) == built(tree)
}

let page = live()
let _ = page.paint_view(view())
n = 2
let after_n = hears_fresh(page)
m = 11
let after_m = hears_fresh(page)
let again = hears_fresh(page)
println("${after_n} ${after_m} ${again}")
println(page.exact_counts())
true true true
answered 0 declined 3

// ── state ───────────────────────────────────────────────────────

state filter: Show = .All
state dark: bool = false
state newest_first: bool = false
state dialog_open: bool = false
state reminded: bool = false
state tasks_ask: Fetch<List<Todo>> = fetch()
state saving: Fetch<Todo> = fetch()
state removing: Fetch<Nothing> = fetch()

// ── the state a page carries ────────────────────────────────────

/// Name the states a server's page carries to the module: what the view
/// reads and a request decides. A state not named here is never shipped.
export fn ship_state() {
    ship("filter", Show.json_shape(), () -> filter.json_text(), (j: string) -> filter_written(j))
    ship("dark", "bool", () -> bool_text(dark), (j: string) -> dark_written(j))
    ship(
        "tasks",
        "[${Todo.json_shape()}]",
        () -> array_of([t.json_text() for t in tasks()]),
        (j: string) -> tasks_written(j),
    )
}

/// What a request for the done tasks in the dark decides, as a server's
/// handler would before it draws the page.
export fn requested() {
    filter = .Done
    dark = true
}

fn filter_written(j: string) -> bool {
    match Show.from_json_text(j) {
        .Ok(shown) -> {
            filter = shown
            true
        },
        .Err(_) -> false,
    }
}

fn dark_written(j: string) -> bool {
    match as_bool(j, "") {
        .Ok(on) -> {
            dark = on
            true
        },
        .Err(_) -> false,
