/// `view` under `theme`, shown by `show`.
export fn app<V: View>(view: fn() -> V, theme: fn() -> Theme, show: fn(Node, Theme) -> void) -> App {
    let nothing: List<Owner> = []
    owned_app(view, theme, show, Cell.new(nothing))
}

/// `app`, whose target keeps `on_screen` — the owner keys of the controls
/// its last paint showed — written by `show`. A target says what an owner
/// is: a control's path where the tree is held, a node's number on a page.
export fn owned_app<V: View>(
    view: fn() -> V,
    theme: fn() -> Theme,
    show: fn(Node, Theme) -> void,
    on_screen: Cell<List<Owner>>,
    stands: Standing = standing(),
) -> App {
    let drawn: fn(Standing) -> Node = (at: Standing) -> rooted(view().describe(at))
    let untold: List<string> = []
    let nodoor: Door? = null
    let nothing: string? = null
    let nobody: string? = null
    App {
        view: Cell.new(drawn),
        theme: Cell.new(theme),
        show: show,
        stands: stands,
        told: Cell.new(untold),
        door: Cell.new(nodoor),
        looping: Cell.new(false),
        jobs: Cell.new(0),
        failed: Cell.new(nothing),
        unsaid: Cell.new(nothing),
        guard: Cell.new(contained_turn),
        noticed: Cell.new(unnoticed),
        asking: Cell.new(nobody),
        standing: on_screen,
        refused: Cell.new(untold),
        dirty: Cell.new(false),
        holding: Cell.new(false),
        asked: Cell.new(false),
        framer: Cell.new(nobody_asks),
        walks: Cell.new(0),
        painting: Cell.new(false),
        frames: Cell.new(0),
        observed: cache(),
    }
}

/// `on` shows `view` under `theme` from now on: the same app on the same
/// target, so a paint already under way paints this view, never the one
/// it replaced. What stood stays on offer: an instance the new view
/// reaches where the old one had it keeps its state.
export fn remounted<V: View>(on: App, view: fn() -> V, theme: fn() -> Theme) {
    on.view.set((at: Standing) -> rooted(view().describe(at)))
    on.theme.set(theme)
}

impl App {
    /// The view as the state stands now, shown. The walk opens the
    /// app's standing, so an instance this paint does not reach is gone
    /// with it.

/// `view` under `theme` on `page`: each paint's patches go to `send` as
/// one frame, and a page that did not change is sent nothing. A page that
/// already shows something is TURNED INTO the view, never drawn over.
export fn paged<V: View>(view: fn() -> V, theme: fn() -> Theme, page: Live, send: fn(Bytes) -> void) -> Paged {
    let notice: Cell<Node?> = Cell.new(null)
    let standing: Cell<List<Owner>> = Cell.new([])
    let made = Paged {
        app: owned_app(
            view,
            theme,
            (root: Node, worn: Theme) -> {
                let patches = page.patches_drawn(root, worn, notice.get())
                standing.set(page.owners())
                if !patches.is_empty() { send(frame(patches, page.told)) }
            },
            standing,
            page.stands,
        ),
        page: page,
    }
    made.app.noticing((words: string?) -> notice.set(noticed_as(words)))
    made
}

/// The notice a failure's words stand as, none when no turn has failed.
once fn wanted() -> Wants { wants() }

/// THE APP: `view` under `theme` on the page, painted now and after every
/// event that ran a handler. Mounting again — from a handler too — turns
/// the same page into the new view.
export fn mount<V: View>(view: fn() -> V, theme: fn() -> Theme = plain) {
    let held? = mounted().get() else {
        let made = paged(view, theme, live(), (sent: Bytes) -> avra_dom_frame(sent))
        mounted().set(made)
        stood(made.app)
        made.app.stands.geometric()
        made.app.stands.first_rows(first_window)
        carry(handed_state().get())
        close()
        made.app.door.set(opened())
        made.page.stood.set(avra_ui_stood())
        made.page.handed.set(handed().get())
        made.app.paint()
        made.app.framer.set(asks_frame)
        made.app.holding.set(true)
        made.app.warn()
        return
    }
    remounted(held.app, view, theme)
    held.app.paint()
    swept(held)
    held.app.warn()
}

// ── what the host calls ─────────────────────────────────────────
// Host fns: each name is the symbol the page's glue calls it by, the one
/// `view` shown in memory, painted once. A target with a viewport says how
/// many rows a windowed list builds before it is told its window (`rows`, none
/// by default: every row), and whether it keeps room for the rows a list
/// leaves unbuilt (`spaced`).
export fn shown<V: View>(view: fn() -> V, rows: int = 0, spaced: bool = false) -> Shown {
    let tree: Cell<Node?> = Cell.new(null)
    let standing: Cell<List<Owner>> = Cell.new([])
    let made = Shown {
        app: owned_app(
            view,
            plain,
            (root: Node, _theme: Theme) -> {
                tree.set(root)
                standing.set([c.owner() for c in controls(root)])
            },
            standing,
        ),
        tree: tree,
    }
    if rows > 0 { made.app.stands.first_rows(rows) }
    if spaced { made.app.stands.geometric() }
    made.app.paint()
    made
}

