/// A recursive view re-entered while `key` is open: its settles keep no read of itself.
fn reentered(key: Key) {
    let own = edge_of(key)
    if !self.asker.views.get().contains(own) { self.asker.views.push(own) }
}

fn closed_frame() -> List<int> {
    let edges = self.asker.pending.get().last()!.get()
