//! `@query` — a fn over a Db whose answer is kept per call. Its written
//! body moves behind a wrapper (WRAP): a call is a CELL of the Db's
//! kernel, named by its arguments' encoding, so its answer stands while
//! everything it read stands and is computed again when one of them
//! moves. The body writes no rows of its own: an insert there is refused,
//! and rows it produces are handed to a named owner as a value
//! (`Rel.replaced`).
//!
//! A kept answer OUTLIVES THE PROCESS where the Db's owner keeps it
//! (`durable_db`): a call no answer here stands for asks the owner for
//! its record, by the query's durable name, its code's hash (`code_hash`:
//! an edit to anything the body reaches reads no old record) and the
//! arguments' hash, and a run that wrote no rows hands its answer over.
//! An answer whose kind does not read back stays in the process.
//!
//! The first seat is the `Db`, or a CONTEXT that answers one through
//! `query_db()` — a call over a context reads what the context holds, so
//! its answer stays in the process (`saved`), re-asked whenever a read it
//! recorded moves. A dense id (`@dense`) is a seat in the process too.
//!
//! Marks shape a query's cell. An answer is digested by its type: a
//! codec's bytes (a `@local` field is no part of them, which is how a
//! reader is cut off on less than the whole answer), else, for an answer
//! that stays in the process, the type's own `fingerprint()`. Under
//! `@scoped_by(f)` the call's dense ids cross under the scope `f` makes of
//! its seats, where the context's `query_scope()` is not it.
//! `@recursive` lets a call re-entered before it settles compute again,
//! a smaller view, where a plain query answers the cycle with the value
//! it last held — or, under `@cycled_by(f)`, with what `f` says stands for
//! the call while its run is open. `@fixpoint(bottom, join)` solves the
//! whole group a cycle makes instead: from `bottom()`, joined until no
//! member grows, and solved again from bottom when any member's read moves. A body that cannot finish its answer says so with
//! `db.unkept()`: the answer reaches its asker and no cell holds it.
//!
//!     @query
//!     fn open_for(db: Db, owner: string) -> int { … }
//!
//! `@over(lister)` rides on a PRODUCER — a query keyed by one value:
//! it implies the `@query` and adds `<name>_listed(db)`, the producer
//! asked once per key the lister answers. "Those asked so far" is never
    all
}

/// The context's one scope, bound where a scoped query's code spells an id. A `Db` has no scope,
/// so a query over the Db alone spells a coded type's ids by their numbers.
fn scope_bound(f: Fn) -> List<Stmts> {
    if !scoped(f) {
        if coded(f).is_empty() { return [] }
        return [scope_let(quote { indexed_scope() })]
    }
    let by? = mark_word(f, "scoped_by") else { return [scope_let(quote { ${name(f.params[0].name)}.query_scope() })] }
    [scope_let(quote { ${by}(..${[name(p.name) for p in f.params]}) })]
}

/// `@query`: the wrapper and the query's contract, from one reading.
export fn query(f: Fn) -> Declared {
    let problems = query_problems(f)
    if !problems.is_empty() { return nothing_made(problems) }
    let kept = kept_name(f)
    Declared {
        made: [
            declares(kept, f.at, kept_source(f, kept)),
            Directive { twin: "", name: f.name, at: f.at, wraps: true, source: wrapper(f) },
            declares(key_name(f), f.at, key_door(f)),
            declares("${f.name}_dropped", f.at, dropped_door(f)),
            declares(row_name(f), f.at, row_source(f)),
        ]
            .concat(held_door(f))
            .concat(seat_door(f))
            .concat(known_door(f))
            .concat(kept_door(f)),
        problems: [],
    }
}

/// Marks a lasting query's `_known` door over a context: an owner opens each so a record may
/// restore a call this process never asked.
export fn query_known(_f: Named) {}

/// `query_known` for a query over the Db alone.
export fn query_known_db(_f: Named) {}

/// `<name>_known(ctx)`: the answers opened under the context's Db with how a call is asked by
/// its spelling — only a lasting query's, so a restore asks none of the process's own work.
fn known_door(f: Fn) -> List<Directive> {
    let asks = named_by(f)
    if fixpoint_words(f) != null { return [] }
    let first = f.params[0]
    let seat = [quote { fn _(${first.name}: ${first.ty}) {} }]
    let door = "${f.name}_known"
    let kept_as = quote { code_keyed(${literal(durable_name(f))}, code_hash(${name(wrapped(f).name)})) }
    let source = if is_db(first.kind) {
        quote {
            @query_known_db
            export fn ${door}(..${seat}) {
                let held = ${kept_name(f)}().under(${db_code(f)})
                held.kept_as(${kept_as})
                ${asks}
            }
        }
    } else {
        quote {
            @query_known
            export fn ${door}(..${seat}) {
                let held = ${kept_name(f)}().under(${db_code(f)})
                held.kept_as(${kept_as})
                ${asks}
            }
        }
    }
    [declares(door, f.at, source)]
}

/// Where a query's answers are kept: a dense-keyed one is named past the process only by its
/// context's speller, and a text-keyed one is asked by its text (`named_by`).
fn kept_source(f: Fn, kept: string) -> Decls {
    quote {
        once fn ${kept}() -> Answers<${f.answer}> {
            answers(${literal(durable_name(f))}, ${literal(f.name)}, ${as_code(bool_node(keyed_densely(f)))}, ${as_code(bool_node(outlives(f)))})
        }
    }
