701:export type Code = { node: Node }
702-/// A STATEMENT template — `quote { let a = 1 }`.
703-export type Stmts = { node: Node }
704-/// One or more MATCH ARMS — `quote { .A(x) -> x }`.
705-export type Arms = { node: Node }
706-/// One or more DECLARATIONS — `quote { impl T { … } }`; what a
707-/// `Directive` carries.
708-export type Decls = { node: Node }
709-/// What a SUGAR means — `quote { ${self.value} ^ -1 }` in a `means()`,
710-/// or a `meaning`'s rewrite. Its holes are nodes of the tree it
