fn paints(name: string, kind: Event, said: Said, trees: List<Node>) -> string {
    let page = live()
    let _ = page.patches(trees[0], default_theme)
    let _ = page.fire(named(page, name)[0], seat_for(kind), said)
    [spoken(page, t, default_theme) for t in trees.drop(1)].join(" | ")
}

