/// name — `on is .Lit`, `on with { … }`, `on catch e -> 0`, `fn maybe(on:
/// bool)`.
fn opens_on(ts: List<Token>, i: int, keywords: List<string>) -> bool {
    let t = ts[i]
    if t.kind != TokenKind.Name || t.text != "on" || !starts_member(ts, i) { return false }
    if i + 1 >= ts.length || ts[i + 1].kind != TokenKind.Name || keywords.contains(ts[i + 1].text) { return false }
    i + 2 >= ts.length ||
        ts[i + 2].lit_matches("(") ||
        ts[i + 2].lit_matches(":") ||
        ends_instance_head(ts[i + 2])
}

/// Whether nothing but marks stands before `i` on its line: a member
/// starts its line, or follows the marks written before it.
fn starts_member(ts: List<Token>, i: int) -> bool {
    if starts_statement(ts, i) { return true }
    let opens? = mark_before(ts, i) else { return false }
    starts_member(ts, opens)
}

/// Where the mark that ends just before `i` opens — `@name`, or `@name(…)`
/// with its arguments on this line — absent when no mark ends there.
fn mark_before(ts: List<Token>, i: int) -> int? {
