    refuse_as_at(
        "defect",
        t.at,
        "defect: `@derive(View)` could not read the library's own vocabulary over `${t.name}`",
        "`Prim`, `Attribute`, `Box`, `Style` and `Stand` are read by their modules' names — one moved",
    )
}

