        "`${f.name}` is shown over `${into}`, and `${into}` is no `state` member of this primitive",
        "name the primitive's own place — `state ${into}: T = …` beside it",
    )
}

fn over_misfit(f: Field, m: Mark, place: Field) -> Diagnostic {
    refuse_as_at(
        "over",
        m.at,
        "what is shown over `${place.name}` is told each paint and may be left out, and `${f.name}` is `${if f.state { "state " } else { "" }}${f.kind.spelled()}`",
        "declare it `${f.name}: ${place.kind.spelled()}? = null`",
    )
}

fn over_marked(f: Field, m: Mark) -> Diagnostic {
    refuse_as_at(
        "over",
        m.at,
        "`${f.name}` shows through its place's attribute, and is marked `@${m.name}` too",
        "drop the mark — the place says what the node holds",
    )
}

