fn part(t: Type, f: Field) -> Part {
    if self.kept_state(f) { return refused(stateful_primitive(f)) }
    let says? = f.says else { return self.marked(f) }
    let marked? = f.marks.first() else { return self.event(t, f, says) }
    refused(marked_event(f, marked))
}

