use @std.queue.{queue, worker, run, Dead, Delivery, HomeError}
use @std.queue_store.durable.{db, stored}
use @std.queue_store.fault.{homed}
use @std.relation.{codec}
use @std.sqlite.{Db, sql}
use @std.time.{ms, sleep}

@codec
type Job = { n: int }

fn wrote(db: Db, d: Delivery<Job>) -> Result<int, string> {
    let _ = db.run(sql("INSERT INTO \"done\" (\"n\") VALUES (?1)", [.Int(d.item.n)])) catch 0
    d.item.n
}

fn main() -> Result<string, HomeError> {
    ctx db = homed(Db.memory())?
    let _ = homed(ctx.db.run(sql("CREATE TABLE \"done\" (\"n\" INTEGER)")))?
    queue<Job> jobs {
        name: "jobs"
        durable: stored<Job>()
    }
    queue<Dead<Job, string>> letters {}
    worker crew {
        reads: jobs
        each: (d: Delivery<Job>) -> wrote(ctx.db, d)
        dead: letters
    }
    let _ = jobs.send(Job { n: 1 })?
    let serving = spawn run(crew)
    sleep(ms(200))
    crew.stop()
    let settled = match serving.await { .Ok(n) -> n, .Err(_) -> 0 - 1 }
    let rows = homed((homed(ctx.db.scalar(sql("SELECT count(*) FROM \"done\"")))?).int())?
    "settled ${settled} | rows ${rows} | depth ${jobs.home().depth()?}"
}

match main() { .Ok(told) -> told, .Err(_) -> "failed" }
use @std.meta.{guarded}

ctx n: int

type Holder = { f: fn(int) -> int }

component box {
    f: fn(int) -> int
}

type Shift = { f: fn(int) -> int }

impl Shift {
    fn spawned_in_method() -> int {
        let t = spawn (self.f)(1)
        t.await
    }
    fn nested_guarded() -> int {
        let f = self.f
        let t = spawn ran(() -> f(1))
        t.await
    }
}

fn ran(body: fn() -> int) -> int {
    let slot: Cell<int> = Cell.new(0 - 1)
    let trapped = guarded(() -> {
        slot.set(body())
        true
    })
    if trapped != null { 0 - 2 } else { slot.get() }
}

fn call(f: fn(int) -> int) -> int { f(1) }

fn direct() -> int {
    ctx n = 5
    let f = (x: int) -> x + ctx.n
    let t = spawn f(1)
    t.await
}

fn plus_n(x: int) -> int { x + ctx.n }

fn named_spawned() -> int {
    ctx n = 5
    let t = spawn plus_n(1)
    t.await
}

fn here() -> int {
    ctx n = 5
    let f = (x: int) -> x + ctx.n
    f(1)
}

fn through_record() -> int {
    ctx n = 5
    let h = Holder { f: (x: int) -> x + ctx.n }
    let t = spawn call(h.f)
    t.await
}

fn through_component() -> int {
    ctx n = 5
    box b {
        f: (x: int) -> x + ctx.n
    }
    let t = spawn call(b.f)
    t.await
}

fn in_method() -> int {
    ctx n = 5
    Shift { f: (x: int) -> x + ctx.n }.spawned_in_method()
}

fn under_guard() -> int {
    ctx n = 5
    Shift { f: (x: int) -> x + ctx.n }.nested_guarded()
}

fn component_in_method() -> int {
    ctx n = 5
    box b {
        f: (x: int) -> x + ctx.n
    }
    Shift { f: b.f }.nested_guarded()
}

spec "ctx read by a lambda run in another task" {
    given "shapes" {
        then "called in this task" { here() == 6 }
        then "a named fn spawned" { named_spawned() == 6 }
        then "through a record field" { through_record() == 6 }
        then "through a component field" { through_component() == 6 }
        then "spawned inside a method" { in_method() == 6 }
        then "spawned inside a method under a guard" { under_guard() == 6 }
        then "a component field, spawned in a method under a guard" { component_in_method() == 6 }
        then "spawned directly" { direct() == 6 }
    }
}
